mapper.select:
SELECT *
FROM pull_task_pull_call_member_attempt
WHERE pull_call_id = #{pullCallId}
  AND lifecycle_status = #{lifecycleStatus}
ORDER BY id ASC

SELECT COALESCE(MAX(attempt_no), 0) + 1
FROM pull_task_pull_call_member_attempt
WHERE group_execution_id = #{groupExecutionId}
  AND participant_type = #{participantType}
  AND participant_ref_id = #{participantRefId}

SELECT *
FROM pull_task_pull_call_member_attempt
WHERE pull_call_id = #{pullCallId}
  AND target_jid = #{targetJid}

mapper.update:
UPDATE pull_task_pull_call_member_attempt
SET lifecycle_status = #{targetStatus},
    submitted_at = #{now},
    updated_at = #{now}
WHERE pull_call_id = #{pullCallId}
  AND lifecycle_status = #{expectedStatus}
  AND active_slot = 1

UPDATE pull_task_pull_call_member_attempt SET lifecycle_status = #{targetStatus}, active_slot = NULL, execution_state = #{executionState}, reason_code = #{reasonCode}, reason_message = #{reasonMessage}, result_at = #{now}, released_at = #{now}, updated_at = #{now} WHERE task_id = #{taskId}
AND group_execution_id = #{groupExecutionId}
AND lifecycle_status = #{expectedStatus} AND EXISTS ( SELECT 1 FROM pull_task_pull_call call_row JOIN protocol_command_outbox outbox_row ON outbox_row.command_id = call_row.command_id WHERE call_row.id = pull_task_pull_call_member_attempt.pull_call_id AND outbox_row.status = #{canceledOutboxStatus} AND outbox_row.deleted_at IS NULL )
